import os
import json

ws = '/home/USER/runs/paper/qwen-ha-u1-turns/frozen/held-out-4/play/users/u061/system/state/workspace'

# Let's look at a few more files to understand format
print("Looking at patterns in other files...")

for f in sorted(os.listdir(ws)):
    if f.endswith('.json') and f not in ['submit.json', 'final_output.json', 'test_output.json']:
        print(f"\n=== {f} ===")
        try:
            with open(f'{ws}/{f}', 'r') as file:
                content = json.load(file)
                print(type(content).__name__, f"with {content}")
        except:
            try:
                with open(f'{ws}/{f}', 'r') as file:
                    print(file.read()[:500])
            except:
                print("Could not read")

# Also look for input-related patterns
